[1] = {id = 1, type = 1, title = "User\u{0020}Agreement", data = "GENNMU\u{0020}GAME\u{0020}Terms\u{0020}of\u{0020}Use\nLast\u{0020}updated:\u{0020}2024/09/01\nThis\u{0020}User\u{0020}Agreement\u{0020}(\"Agreement\")\u{0020}is\u{0020}a\u{0020}legal\u{0020}agreement\u{0020}between\u{0020}you\u{0020}and\u{0020}GENNMUGAME\u{0020}CO.,\u{0020}LTD.\u{0020}(\"gennmu,\"\u{0020}\"we,\"\u{0020}\"our,\"\u{0020}or\u{0020}\"us\")\u{0020}regarding\u{0020}the\u{0020}Services\u{0020}you\u{0020}use.\u{0020}\"Services\"\u{0020}include\u{0020}our\u{0020}Games,\u{0020}websites,\u{0020}software,\u{0020}and\u{0020}other\u{0020}materials\u{0020}related\u{0020}to\u{0020}our\u{0020}Games.\u{0020}\"Game\"\u{0020}refers\u{0020}to\u{0020}any\u{0020}game\u{0020}you\u{0020}download\u{0020}and\u{0020}access\u{0020}under\u{0020}this\u{0020}Agreement,\u{0020}regardless\u{0020}of\u{0020}the\u{0020}platform.\nIf\u{0020}you\u{0020}are\u{0020}a\u{0020}resident\u{0020}of\u{0020}the\u{0020}United\u{0020}States,\u{0020}Article\u{0020}17\u{0020}applies\u{0020}to\u{0020}you.\u{0020}For\u{0020}other\u{0020}countries,\u{0020}refer\u{0020}to\u{0020}our\u{0020}terms\u{0020}and\u{0020}conditions\u{0020}below.\nPlease\u{0020}read\u{0020}these\u{0020}terms\u{0020}carefully\u{0020}before\u{0020}registering\u{0020}or\u{0020}using\u{0020}our\u{0020}Services,\u{0020}especially\u{0020}those\u{0020}concerning\u{0020}liability.\u{0020}These\u{0020}terms\u{0020}may\u{0020}change,\u{0020}and\u{0020}we\u{0020}encourage\u{0020}you\u{0020}to\u{0020}review\u{0020}them\u{0020}regularly.\u{0020}By\u{0020}continuing\u{0020}to\u{0020}use\u{0020}our\u{0020}Services\u{0020}after\u{0020}updates,\u{0020}you\u{0020}accept\u{0020}the\u{0020}revised\u{0020}terms.\nIF\u{0020}YOU\u{0020}ARE\u{0020}UNDER\u{0020}18\u{0020}OR\u{0020}THE\u{0020}AGE\u{0020}OF\u{0020}MAJORITY\u{0020}WHERE\u{0020}YOU\u{0020}LIVE,\u{0020}YOU\u{0020}MUST\u{0020}HAVE\u{0020}A\u{0020}PARENT\u{0020}OR\u{0020}GUARDIAN'S\u{0020}PERMISSION\u{0020}TO\u{0020}OPEN\u{0020}AN\u{0020}ACCOUNT,\u{0020}AND\u{0020}THEY\u{0020}MUST\u{0020}AGREE\u{0020}TO\u{0020}THIS\u{0020}AGREEMENT.\u{0020}IF\u{0020}YOU\u{0020}ARE\u{0020}A\u{0020}PARENT\u{0020}OR\u{0020}GUARDIAN,\u{0020}YOU\u{0020}ARE\u{0020}RESPONSIBLE\u{0020}FOR\u{0020}ALL\u{0020}ACTIVITIES\u{0020}ON\u{0020}THE\u{0020}ACCOUNT\u{0020}CREATED\u{0020}BY\u{0020}YOUR\u{0020}MINOR,\u{0020}INCLUDING\u{0020}ANY\u{0020}TRANSACTIONS.\nArticle\u{0020}1:\u{0020}GENNMU\u{0020}Account\u{0020}&\u{0020}Password\nTo\u{0020}use\u{0020}HazeReverb\u{0020}Services,\u{0020}you\u{0020}must\u{0020}register\u{0020}for\u{0020}a\u{0020}HazeReverb\u{0020}Account.\u{0020}By\u{0020}registering,\u{0020}you\u{0020}agree\u{0020}to\u{0020}this\u{0020}Agreement.\u{0020}If\u{0020}you\u{0020}do\u{0020}not\u{0020}accept\u{0020}the\u{0020}terms,\u{0020}you\u{0020}cannot\u{0020}create\u{0020}an\u{0020}Account.\nYou\u{0020}must\u{0020}provide\u{0020}and\u{0020}maintain\u{0020}accurate\u{0020}information.\u{0020}Failure\u{0020}to\u{0020}do\u{0020}so\u{0020}may\u{0020}result\u{0020}in\u{0020}suspension\u{0020}or\u{0020}termination.\u{0020}Usernames\u{0020}must\u{0020}not\u{0020}be\u{0020}offensive;\u{0020}we\u{0020}may\u{0020}request\u{0020}changes\u{0020}for\u{0020}terms\u{0020}violations.\nKeep\u{0020}your\u{0020}Account\u{0020}information\u{0020}confidential.\u{0020}You\u{0020}are\u{0020}responsible\u{0020}for\u{0020}all\u{0020}activities\u{0020}under\u{0020}your\u{0020}Account,\u{0020}even\u{0020}if\u{0020}unauthorized.\nYou\u{0020}may\u{0020}not\u{0020}gift,\u{0020}lend,\u{0020}transfer,\u{0020}or\u{0020}use\u{0020}another's\u{0020}Account.\u{0020}Unauthorized\u{0020}use\u{0020}may\u{0020}lead\u{0020}to\u{0020}immediate\u{0020}termination\u{0020}without\u{0020}a\u{0020}refund.\nWe\u{0020}may\u{0020}terminate\u{0020}your\u{0020}Account\u{0020}for\u{0020}non-compliance.\u{0020}You\u{0020}cannot\u{0020}re-register\u{0020}without\u{0020}permission.\nReport\u{0020}any\u{0020}unauthorized\u{0020}use\u{0020}or\u{0020}security\u{0020}breach\u{0020}immediately.\u{0020}We\u{0020}may\u{0020}suspend\u{0020}or\u{0020}terminate\u{0020}the\u{0020}Account\u{0020}and\u{0020}provide\u{0020}a\u{0020}method\u{0020}to\u{0020}change\u{0020}your\u{0020}password.\nWe\u{0020}will\u{0020}never\u{0020}ask\u{0020}for\u{0020}your\u{0020}password.\u{0020}Keep\u{0020}it\u{0020}secure;\u{0020}any\u{0020}unauthorized\u{0020}use\u{0020}will\u{0020}be\u{0020}your\u{0020}responsibility.\nIf\u{0020}you\u{0020}forget\u{0020}your\u{0020}password,\u{0020}notify\u{0020}us.\u{0020}We\u{0020}are\u{0020}not\u{0020}responsible\u{0020}for\u{0020}losses\u{0020}due\u{0020}to\u{0020}forgotten\u{0020}passwords.\nFollow\u{0020}our\u{0020}procedures\u{0020}to\u{0020}continue\u{0020}using\u{0020}your\u{0020}Account\u{0020}if\u{0020}you\u{0020}change\u{0020}your\u{0020}device.\nYou\u{0020}can\u{0020}request\u{0020}Account\u{0020}deletion\u{0020}by\u{0020}following\u{0020}our\u{0020}guidelines.\u{0020}Deletion\u{0020}will\u{0020}remove\u{0020}all\u{0020}game\u{0020}data.\u{0020}Unlinking\u{0020}your\u{0020}Account\u{0020}will\u{0020}restrict\u{0020}access\u{0020}to\u{0020}certain\u{0020}games.\nArticle\u{0020}2:\u{0020}Statement\nThis\u{0020}Statement\u{0020}may\u{0020}change\u{0020}if\u{0020}minor\u{0020}protection\u{0020}policies\u{0020}in\u{0020}your\u{0020}country/region\u{0020}change.\nYou\u{0020}confirm\u{0020}you\u{0020}are\u{0020}over\u{0020}13.\u{0020}If\u{0020}you\u{0020}are\u{0020}underage\u{0020}according\u{0020}to\u{0020}local\u{0020}laws,\u{0020}your\u{0020}parent\u{0020}or\u{0020}guardian\u{0020}must\u{0020}agree\u{0020}to\u{0020}this\u{0020}Agreement\u{0020}and\u{0020}consent\u{0020}to\u{0020}your\u{0020}use\u{0020}of\u{0020}our\u{0020}Services.\nBy\u{0020}registering\u{0020}and\u{0020}logging\u{0020}in,\u{0020}we\u{0020}assume\u{0020}you\u{0020}meet\u{0020}the\u{0020}legal\u{0020}age\u{0020}requirements.\u{0020}If\u{0020}we\u{0020}discover\u{0020}personal\u{0020}information\u{0020}from\u{0020}someone\u{0020}under\u{0020}13,\u{0020}we\u{0020}may\u{0020}delete\u{0020}it\u{0020}as\u{0020}required\u{0020}by\u{0020}law.\nArticle\u{0020}3:\u{0020}Application\u{0020}Scope\u{0020}of\u{0020}the\u{0020}Agreement\nThis\u{0020}Agreement\u{0020}governs\u{0020}the\u{0020}rights\u{0020}and\u{0020}obligations\u{0020}related\u{0020}to\u{0020}the\u{0020}Services\u{0020}provided.\u{0020}Game\u{0020}management\u{0020}rules\u{0020}available\u{0020}on\u{0020}the\u{0020}platform\u{0020}or\u{0020}within\u{0020}the\u{0020}game\u{0020}also\u{0020}form\u{0020}part\u{0020}of\u{0020}this\u{0020}Agreement.\nArticle\u{0020}4:\u{0020}Scope\u{0020}of\u{0020}Services\nServices\u{0020}include\u{0020}all\u{0020}game\u{0020}content\u{0020}accessed\u{0020}via\u{0020}your\u{0020}device\u{0020}but\u{0020}exclude\u{0020}internet\u{0020}service\u{0020}costs\u{0020}and\u{0020}hardware.\u{0020}You\u{0020}are\u{0020}responsible\u{0020}for\u{0020}these\u{0020}expenses.\nVirtual\u{0020}items\u{0020}purchased\u{0020}in-game\u{0020}are\u{0020}handled\u{0020}through\u{0020}Google\u{0020}Play\u{0020}(Android)\u{0020}or\u{0020}in-app\u{0020}purchases\u{0020}(iOS).\u{0020}Ensure\u{0020}you\u{0020}agree\u{0020}to\u{0020}payment\u{0020}partners'\u{0020}terms.\u{0020}If\u{0020}a\u{0020}transaction\u{0020}fails,\u{0020}your\u{0020}purchase\u{0020}will\u{0020}not\u{0020}be\u{0020}completed.\u{0020}Once\u{0020}payment\u{0020}is\u{0020}processed,\u{0020}we\u{0020}will\u{0020}fulfill\u{0020}your\u{0020}order\u{0020}promptly.\nArticle\u{0020}5:\u{0020}Personal\u{0020}Information\nWe\u{0020}use\u{0020}safety\u{0020}measures\u{0020}and\u{0020}technology\u{0020}to\u{0020}protect\u{0020}your\u{0020}personal\u{0020}information\u{0020}from\u{0020}unauthorized\u{0020}use\u{0020}or\u{0020}access.\nYour\u{0020}personal\u{0020}data\u{0020}is\u{0020}used\u{0020}to\u{0020}fulfill\u{0020}this\u{0020}Agreement\u{0020}and\u{0020}in\u{0020}accordance\u{0020}with\u{0020}relevant\u{0020}laws.\nWe\u{0020}may\u{0020}use\u{0020}aggregated\u{0020}membership\u{0020}statistics\u{0020}for\u{0020}legal\u{0020}and\u{0020}public\u{0020}purposes,\u{0020}provided\u{0020}they\u{0020}do\u{0020}not\u{0020}disclose\u{0020}personal\u{0020}identity.\nWe\u{0020}may\u{0020}disclose\u{0020}personal\u{0020}information\u{0020}or\u{0020}game\u{0020}data\u{0020}if\u{0020}required\u{0020}by\u{0020}law\u{0020}or\u{0020}to\u{0020}protect\u{0020}our\u{0020}rights,\u{0020}property,\u{0020}or\u{0020}safety,\u{0020}or\u{0020}to\u{0020}respond\u{0020}to\u{0020}service\u{0020}requests.\nReview\u{0020}our\u{0020}Privacy\u{0020}Policy\u{0020}for\u{0020}details\u{0020}on\u{0020}how\u{0020}we\u{0020}protect\u{0020}and\u{0020}use\u{0020}your\u{0020}personal\u{0020}information.\nArticle\u{0020}6:\u{0020}Game\u{0020}Interaction\nOur\u{0020}games\u{0020}may\u{0020}allow\u{0020}you\u{0020}to\u{0020}play\u{0020}against\u{0020}or\u{0020}with\u{0020}other\u{0020}users,\u{0020}either\u{0020}randomly\u{0020}selected\u{0020}by\u{0020}us\u{0020}or\u{0020}from\u{0020}your\u{0020}contacts.\u{0020}We\u{0020}may\u{0020}display\u{0020}past\u{0020}opponents’\u{0020}names\u{0020}for\u{0020}easy\u{0020}re-matching.\nWe\u{0020}may\u{0020}use\u{0020}criteria\u{0020}such\u{0020}as\u{0020}past\u{0020}scores,\u{0020}or\u{0020}game\u{0020}level\u{0020}for\u{0020}user\u{0020}selection.\nBy\u{0020}playing\u{0020}our\u{0020}games,\u{0020}you\u{0020}agree\u{0020}that\u{0020}your\u{0020}display\u{0020}name,\u{0020}scores,\u{0020}avatar,\u{0020}and\u{0020}status\u{0020}may\u{0020}be\u{0020}publicly\u{0020}displayed\u{0020}without\u{0020}payment.\u{0020}Other\u{0020}users\u{0020}can\u{0020}search\u{0020}for\u{0020}you\u{0020}by\u{0020}User-ID,\u{0020}but\u{0020}only\u{0020}your\u{0020}display\u{0020}name\u{0020}will\u{0020}be\u{0020}shown\u{0020}publicly.\nArticle\u{0020}7:\u{0020}Virtual\u{0020}In-Game\u{0020}Items\u{0020}(Currency)\nVirtual\u{0020}items\u{0020}(currency)\u{0020}will\u{0020}be\u{0020}deducted\u{0020}in\u{0020}the\u{0020}order\u{0020}of\u{0020}purchased\u{0020}items\u{0020}first,\u{0020}followed\u{0020}by\u{0020}any\u{0020}free\u{0020}items.\nYou\u{0020}may\u{0020}buy\u{0020}virtual\u{0020}items\u{0020}(currency)\u{0020}with\u{0020}real\u{0020}currency.\u{0020}They\u{0020}cannot\u{0020}be\u{0020}exchanged\u{0020}for\u{0020}real\u{0020}money,\u{0020}physical\u{0020}goods,\u{0020}or\u{0020}services,\u{0020}and\u{0020}must\u{0020}be\u{0020}obtained\u{0020}directly\u{0020}from\u{0020}us.\nAll\u{0020}virtual\u{0020}items\u{0020}(currency)\u{0020}are\u{0020}non-refundable\u{0020}unless\u{0020}required\u{0020}by\u{0020}law\u{0020}due\u{0020}to\u{0020}the\u{0020}nature\u{0020}of\u{0020}online\u{0020}services.\nWe\u{0020}can\u{0020}modify\u{0020}or\u{0020}remove\u{0020}virtual\u{0020}items\u{0020}(currency)\u{0020}at\u{0020}our\u{0020}discretion\u{0020}and\u{0020}are\u{0020}not\u{0020}liable\u{0020}for\u{0020}any\u{0020}losses\u{0020}if\u{0020}your\u{0020}account\u{0020}is\u{0020}suspended\u{0020}or\u{0020}terminated.\nChanges\u{0020}to\u{0020}in-game\u{0020}items\u{0020}or\u{0020}payment\u{0020}standards\u{0020}are\u{0020}normal,\u{0020}and\u{0020}you\u{0020}will\u{0020}not\u{0020}be\u{0020}compensated\u{0020}for\u{0020}these\u{0020}adjustments.\nArticle\u{0020}8:\u{0020}Operation\u{0020}&\u{0020}User\u{0020}Responsibilities\nWe\u{0020}maintain\u{0020}our\u{0020}systems\u{0020}to\u{0020}a\u{0020}reasonable\u{0020}standard\u{0020}but\u{0020}are\u{0020}not\u{0020}liable\u{0020}for\u{0020}system\u{0020}failures.\nFollow\u{0020}all\u{0020}applicable\u{0020}laws.\u{0020}If\u{0020}restricted\u{0020}by\u{0020}law,\u{0020}stop\u{0020}using\u{0020}the\u{0020}Services\u{0020}and\u{0020}ensure\u{0020}your\u{0020}information\u{0020}is\u{0020}accurate.\nYou\u{0020}are\u{0020}responsible\u{0020}for\u{0020}any\u{0020}Content\u{0020}you\u{0020}upload\u{0020}or\u{0020}transmit.\u{0020}We\u{0020}may\u{0020}delete\u{0020}Content\u{0020}that\u{0020}violates\u{0020}terms\u{0020}or\u{0020}harms\u{0020}our\u{0020}reputation\u{0020}but\u{0020}are\u{0020}not\u{0020}liabl