nt.\n(d)\u{0020}Losses\u{0020}arising\u{0020}from\u{0020}technical\u{0020}failures\u{0020}or\u{0020}availability\u{0020}issues\u{0020}beyond\u{0020}our\u{0020}control.\n(e)\u{0020}Losses\u{0020}related\u{0020}to\u{0020}third-party\u{0020}websites,\u{0020}content,\u{0020}products,\u{0020}or\u{0020}services\u{0020}linked\u{0020}through\u{0020}our\u{0020}Services.\u{0020}We\u{0020}do\u{0020}not\u{0020}endorse\u{0020}or\u{0020}control\u{0020}these\u{0020}third-party\u{0020}sites\u{0020}or\u{0020}their\u{0020}content.\nWe\u{0020}are\u{0020}responsible\u{0020}only\u{0020}for\u{0020}foreseeable\u{0020}losses\u{0020}or\u{0020}damages\u{0020}arising\u{0020}directly\u{0020}from\u{0020}our\u{0020}negligence\u{0020}or\u{0020}violation\u{0020}of\u{0020}this\u{0020}Agreement,\u{0020}up\u{0020}to\u{0020}the\u{0020}amount\u{0020}you\u{0020}paid\u{0020}us\u{0020}within\u{0020}the\u{0020}90\u{0020}days\u{0020}preceding\u{0020}your\u{0020}claim.\nSome\u{0020}jurisdictions\u{0020}do\u{0020}not\u{0020}allow\u{0020}the\u{0020}exclusion\u{0020}of\u{0020}certain\u{0020}warranties\u{0020}or\u{0020}limitations\u{0020}of\u{0020}liability.\u{0020}In\u{0020}such\u{0020}cases,\u{0020}these\u{0020}terms\u{0020}may\u{0020}not\u{0020}apply\u{0020}to\u{0020}you.\u{0020}You\u{0020}may\u{0020}have\u{0020}additional\u{0020}legal\u{0020}rights\u{0020}in\u{0020}your\u{0020}jurisdiction,\u{0020}which\u{0020}this\u{0020}Agreement\u{0020}does\u{0020}not\u{0020}prejudice.\nArticle\u{0020}14:\u{0020}Indemnity\nYou\u{0020}agree\u{0020}to\u{0020}indemnify\u{0020}and\u{0020}hold\u{0020}GENNMU\u{0020}and\u{0020}its\u{0020}members,\u{0020}directors,\u{0020}officers,\u{0020}employees,\u{0020}and\u{0020}agents\u{0020}harmless\u{0020}from\u{0020}any\u{0020}costs,\u{0020}losses,\u{0020}claims,\u{0020}damages,\u{0020}or\u{0020}expenses\u{0020}(including\u{0020}attorney\u{0020}fees)\u{0020}arising\u{0020}from\u{0020}your\u{0020}misrepresentation,\u{0020}negligence,\u{0020}omission,\u{0020}or\u{0020}breach\u{0020}of\u{00