tten\u{0020}consent\u{0020}from\u{0020}GENNMU.\u{0020}GENNMU\u{0020}reserves\u{0020}the\u{0020}right\u{0020}to\u{0020}terminate\u{0020}services\u{0020}if\u{0020}this\u{0020}is\u{0020}violated.\u{0020}GENNMU\u{0020}may\u{0020}assign,\u{0020}transfer,\u{0020}or\u{0020}subcontract\u{0020}its\u{0020}rights\u{0020}or\u{0020}obligations\u{0020}at\u{0020}any\u{0020}time.\nArticle\u{0020}20:\u{0020}Miscellaneous\nWe\u{0020}urge\u{0020}you\u{0020}to\u{0020}read\u{0020}this\u{0020}Agreement\u{0020}carefully,\u{0020}particularly\u{0020}the\u{0020}clauses\u{0020}limiting\u{0020}liability\u{0020}and\u{0020}restricting\u{0020}user\u{0020}rights.\nThe\u{0020}terms\u{0020}of\u{0020}this\u{0020}Agreement,\u{0020}along\u{0020}with\u{0020}our\u{0020}privacy\u{0020}policy\u{0020}and\u{0020}other\u{0020}statements,\u{0020}form\u{0020}a\u{0020}complete\u{0020}legal\u{0020}understanding\u{0020}and\u{0020}have\u{0020}the\u{0020}same\u{0020}binding\u{0020}effect.", "0", "0"},
[2] = {id = 2, type = 2, title = "Privacy\u{0020}Policy", data = "Privacy\u{0020}Policy\nLast\u{0020}updated:2024/09/01\n\nThe\u{0020}Data\u{0020}Controller\u{0020}under\u{0020}this\u{0020}Privacy\u{0020}Policy\u{0020}is\u{0020}GENNMUGAME\u{0020}CO.,\u{0020}LTD.\u{0020}(\"gennmu,\"\u{0020}\"we,\"\u{0020}\"our,\"\u{0020}or\u{0020}\"us\").\n\nWe\u{0020}value\u{0020}the\u{0020}privacy\u{0020}of\u{0020}individuals\u{0020}(\"you\"\u{0020}or\u{0020}\"User\")\u{0020}who\u{0020}visit\u{0020}our\u{0020}websites,\u{0020}use\u{0020}or\u{0020}access\u{0020}our\u{0020}games\u{0020}on\u{0020}mobile\u{0020}devices,\u{0020}PCs,\u{0020}or\u{0020}other\u{0020}platforms\u{0020}(\"gennmu\u{0020}Game(s)\"\u{0020}or\u{0020}\"Game(s)\"),\u{0020}and/or\u{0020}use\u{0020}our\u{0020}services\u{0020}(\"gennmu\u{0020}Services\"\u{0020}or\u{0020}\"our\u{0020}services\").\n\nThis\u{0020}Policy\u{0020}describes\u{0020}why\u{0020}and\u{0020}how\u{0020}we\u{0020}collect,\u{0020}store,\u{0020}and\u{0020}use\u{0020}your\u{0020}personal\u{0020}data,\u{0020}and\u{0020}the\u{0020}choices\u{0020}you\u{0020}have\u{0020}regarding\u{0020}it.\u{0020}By\u{0020}using\u{0020}our\u{0020}websites\u{0020}or\u{0020}Games,\u{0020}you\u{0020}acknowledge\u{0020}that\u{0020}you\u{0020}have\u{0020}read,\u{0020}understood,\u{0020}and\u{0020}accepted\u{0020}the\u{0020}following\u{0020}terms.\u{0020}If\u{0020}you\u{0020}do\u{0020}not\u{0020}agree\u{0020}with\u{0020}any\u{0020}of\u{0020}these\u{0020}terms,\u{0020}some\u{0020}basic\u{0020}functions\u{0020}in\u{0020}the\u{0020}Game\u{0020}may\u{0020}not\u{0020}work\u{0020}properly.\nThe\u{0020}minimum\u{0020}age\u{0020}to\u{0020}create\u{0020}an\u{0020}Account\u{0020}(\"Account\")\u{0020}is\u{0020}13.\u{0020}If\u{0020}the\u{0020}age\u{0020}of\u{0020}consent\u{0020}for\u{0020}data\u{0020}collection\u{0020}is\u{0020}higher\u{0020}in\u{0020}certain\u{0020}countries,\u{0020}we\u{0020}require\u{0020}parental\u{0020}or\u{0020}guardian\u{0020}consent\u{0020}before\u{0020}creating\u{0020}an\u{0020}Account.\n\nWe\u{0020}may\u{0020}amend\u{0020}the\u{0020}Policy\u{0020}periodically.\u{0020}We\u{0020}will\u{0020}notify\u{0020}you\u{0020}by\u{0020}updating\u{0020}the\u{0020}date\u{0020}at\u{0020}the\u{0020}top\u{0020}of\u{0020}this\u{0020}Privacy\u{0020}Policy.\u{0020}If\u{0020}any\u{0020}material\u{0020}changes\u{0020}are\u{0020}made,\u{0020}your\u{0020}consent\u{0020}(or\u{0020}parental/guardian\u{0020}consent,\u{0020}if\u{0020}applicable)\u{0020}will\u{0020}be\u{0020}requested\u{0020}again.\u{0020}By\u{0020}continuing\u{0020}to\u{0020}use\u{0020}our\u{0020}Services,\u{0020}you\u{0020}agree\u{0020}to\u{0020}the\u{0020}updated\u{0020}terms.\u{0020}If\u{0020}you\u{0020}disagree,\u{0020}please\u{0020}stop\u{0020}using\u{0020}our\u{0020}Services.\n\n1.What\u{0020}Data\u{0020}We\u{0020}Collect\u{0020}and\u{0020}Process\u{0020}\n(1)Data\u{0020}You\u{0020}Provide\u{0020}Directly\ni.\u{0020}Account\u{0020}Data:Email\u{0020}address,\u{0020}password,\u{0020}username,\u{0020}nickname,\u{0020}profile\u{0020}picture.\nii.Customer\u{0020}Support\u{0020}Information.Data\u{0020}from\u{0020}support\u{0020}interactions,\u{0020}such\u{0020}as\u{0020}purchase\u{0020}details,\u{0020}device\u{0020}info,\u{0020}user\u{0020}ID,\u{0020}and\u{0020}chat\u{0020}data.\niii.Additional\u{0020}Data:\u{0020}Information\u{0020}from\u{0020}discussions,\u{0020}feedback,\u{0020}surveys,\u{0020}or\u{0020}events\u{0020}(e.g.,\u{0020}name,\u{0020}ID\u{0020}number,\u{0020}address\u{0020}for\u{0020}prize\u{0020}distribution).\n(2)Data\u{0020}We\u{0020}Collect\u{0020}on\u{0020}an\u{0020}Ongoing\u{0020}Basis\niv.Guest\u{0020}Login\u{0020}Information:OpenID\u{0020}for\u{0020}each\u{0020}guest\u{0020}login.\nv.IP\u{0020}Address:Used\u{0020}to\u{0020}determine\u{0020}location,\u{0020}manage\u{0020}regional\u{0020}restrictions,\u{0020}and\u{0020}resolve\u{0020}account\u{0020}disputes.\nvi.Transaction\u{0020}Information:In-app\u{0020}purchase\u{0020}details\u{0020}(e.g.,\u{0020}order\u{0020}number,\u{0020}product,\u{0020}cost),\u{0020}device\u{0020}info.\nvii.Usage\u{0020}Data:\u{0020}Gameplay\u{0020}data,\u{0020}game\u{0020}behavior,\u{0020}log\u{0020}information,\u{0020}statistics.\nviii.\u{0020}Device\u{0020}Data:Device\u{0020}name,\u{0020}model,\u{0020}OS\u{0020}version,\u{0020}unique\u{0020}identifiers.\nix.Security\u{0020}Information:Data\u{0020}for\u{0020}ensuring\u{0020}game\u{0020}security\u{0020}and\u{0020}fair\u{0020}play.\nx.\u{0020}Advertising\u{0020}Information:Data\u{0020}to\u{0020}track\u{0020}ad\u{0020}success\u{0020}and\u{0020}maintain\u{0020}service\u{0020}security.\u{0020}\n(3)Data\u{0020}We\u{0020}Collect\u{0020}from\u{0020}Third\u{0020}Parties\ni.Social\u{0020}Media\u{0020}Information:Data\u{0020}from\u{0020}connected\u{0020}accounts\u{0020}(e.g.,\u{0020}Google,\u{0020}Apple).\nii.\u{0020}Other\u{0020}Third-Party\u{0020}Information:Data\u{0020}from\u{0020}sources\u{0020}like\u{0020}ad\u{0020}networks.\n\n2.\u{0020}Why\u{0020}We\u{0020}Collect\u{0020}and\u{0020}Process\u{0020}Your\u{0020}Personal\u{0020}Data\n(1)\u{0020}We\u{0020}collect,\u{0020}use,\u{0020}store,\u{0020}and\u{0020}process\u{0020}your\u{0020}personal\u{0020}data\u{0020}based\u{0020}on:\nLawfulness,\u{0020}fairness,\u{0020}and\u{0020}transparency;\nYour\u{0020}consent\u{0020}(which\u{0020}may\u{0020}be\u{0020}requested\u{0020}periodically);\nLegitimate\u{0020}purposes;\nRelevance\u{0020}and\u{0020}necessity\u{0020}for\u{0020}these\u{0020}purposes;\nEnsuring\u{0020}security\u{0020}of\u{0020}your\u{0020}data;\nCompliance\u{0020}with\u{0020}our\u{0020}Terms\u{0020}of\u{0020}Service\u{0020}and\u{0020}provision\u{0020}of\u{0020}our\u{0020}Services;\nLegitimate\u{0020}interests;\nCompliance\u{0020}with\u{0020}legal\u{0020}and\u{0020}regulatory\u{0020}requirements.\n(2)We\u{0020}collect\u{0020}and\u{0020}process\u{0020}your\u{0020}personal\u{0020}data\u{0020}to:\nManage\u{0020}access\u{0020}to\u{0020}our\u{0020}services;\nAnalyze\u{0020}and\u{0020}improve\u{0020}our\u{0020}services,\u{0020}including\u{0020}user\u{0020}support\u{0020}and\u{0020}security;\nCorrect\u{0020}errors\u{0020}and\u{0020}address\u{0020}user\u{0020}preferences;\nDevelop\u{0020}new\u{0020}services\u{0020}and\u{0020}enhance\u{0020}user\u{0020}experience;\nVerify\u{0020}and\u{0020}confirm\u{0020}payments;\nDeliver\u{0020}relevant\u{0020}advertising;\nFacilitate\u{0020}communication\u{0020}and\u{0020}enforce\u{0020}policy\u{0020}compliance;\nPersonalize\u{0020}your\u{0020}experience\u{0020}and\u{0020}provide\u{0020}updates;\nProtect\u{0020}service\u{0020}integrity,\u{0020}fulfill\u{0020}legal\u{0020}obligations,\u{0020}and\u{0020}enforce\u{0020}our\u{0020}Terms\u{0020}of\u{0020}Service;\nTrack\u{0020}usage\u{0020}to\u{0020}optimize\u{0020}services\u{0020}and\u{0020}prevent\u{0020}fraud;\nInvestigate\u{0020}claims,\u{0020}legal\u{0020}issues,\u{0020}and\u{0020}policy\u{0020}violations;\nComply\u{0020}with\u{0020}applicable\u{0020}laws\u{0020}and\u{0020}regulations.\n3.Advertisements\u{0020}and\u{0020}Your\u{0020}Choices\nPersonalized\u{0020}Advertisements:\nWith\u{0020}your\u{0020}consent,\u{0020}we\u{0020}may\u{0020}use\u{0020}your\u{0020}data\u{0020}to\u{0020}deliver\u{0020}and\u{0020}improve\u{0020}personalized\u{0020}ads\u{0020}and\u{0020}marketing\u{0020}activities.\nWe\u{0020}may\u{0020}also\u{0020}use\u{0020}your\u{0020}data\u{0020}for\u{0020}market\u{0020}research\u{0020}or\u{0020}surveys\u{0020}via\u{0020}authorized\u{0020}contractors.\nOpt-Out:\nYou\u{0020}can\u{0020}opt-out\u{0020}of\u{0020}marketing\u{0020}communications\u{0020}by\u{0020}following\u{0020}provided\u{0020}instructions\u{0020}(e.g.,\u{0020}email,\u{0020}app\u{0020}settings).\u{0020}For\u{0020}instance,\u{0020}disable\u{0020}push\u{0020}notifications\u{0020}in\u{0020}app\u{0020}settings\u{0020}(iOS/Android).\nConsent\u{0020}Withdrawal:\nYou\u{0020}can\u{0020}withdraw\u{0020}consent\u{0020}at\u{0020}any\u{0020}time,\u{0020}which\u{0020}will\u{0020}not\u{0020}affect\u{0020}the\u{0020}lawfulness\u{0020}of\u{0020}data\u{0020}usage\u{0020}prior\u{0020}to\u{0020}withdrawal.\u{0020}We\u{0020}do\u{0020}not\u{0020}target\u{0020}minors\u{0020}with\u{0020}advertisements.\n4.Sharing\u{0020}Your\u{0020}Personal\u{0020}Data\nDirect\u{0020}Identifiers:\nWe\u{0020}do\u{0020}not\u{0020}share\u{0020}personally\u{0020}identifiable\u{0020}data\u{0020}(e.g.,\u{0020}name,\u{0020}email)\u{0020}without:\ni.\u{0020}Your\u{0020}consent;\nii.\u{0020}Legal\u{0020}requirements\u{0020}or\u{0020}law\u{0020}enforcement\u{0020}requests;\niii.\u{0020}Preventing\u{0020}harm\u{0020}or\u{0020}investigating\u{0020}illegal\u{0020}activity;\niv.\u{0020}Protecting\u{0020}vital\u{0020}interests\u{0020}or\u{0020}public\u{0020}security;\nv.\u{0020}Business\u{0020}transactions\u{0020}(e.g.,\u{0020}sale\u{0020}of\u{0020}assets).\nNon-Identifying\u{0020}Data:\nWe\u{0020}may\u{0020}share\u{0020}anonymized\u{0020}or\u{0020}aggregated\u{0020}data\u{0020}with\u{0020}third\u{0020}parties.\nSpecific\u{0020}Sharing\u{0020}Scenarios:\ni.In-Game\u{0020}Users:Your\u{0020}profile\u{0020}and\u{0020}in-game\u{0020}activities\u{0020}may\u{0020}be\u{0020}visible\u{0020}to\u{0020}other\u{0020}players\u{0020}based\u{0020}on\u{0020}privacy\u{0020}settings.\nii.Authorities:\u{0020}We\u{0020}may\u{0020}disclose\u{0020}data\u{0020}to\u{0020}comply\u{0020}with\u{0020}legal\u{0020}requirements\u{0020}or\u{0020}protect\u{0020}our\u{0020}interests.\niii.Related\u{0020}Companies:\u{0020}Shared\u{0020}for\u{0020}support,\u{0020}marketing,\u{0020}or\u{0020}technical\u{0020}operations,\u{0020}adhering\u{0020}to\u{0020}this\u{0020}policy.\niv.Business\u{0020}Transfers:\u{0020}Data\u{0020}may\u{0020}be\u{0020}disclosed\u{0020}in\u{0020}business\u{0020}transitions.\nv.Analytics\u{0020}Providers:\u{0020}Data\u{0020}shared\u{0020}with\u{0020}services\u{0020}like\u{0020}Appsflyer\u{0020}and\u{0020}Firebase\u{0020}for\u{0020}analytics.\nvi.Logistics\u{0020}Providers:\u{0020}Address\u{0020}and\u{0020}phone\u{0020}number\u{0020}shared\u{0020}for\u{0020}prize\u{0020}delivery.\nvii.Third-Party\u{0020}Service\u{0020}Providers:\u{0020}Data\u{0020}shared\u{0020}with\u{0020}providers\u{0020}for\u{0020}login,\u{0020}payments,\u{0020}customer\u{0020}support,\u{0020}cloud\u{0020}services,\u{0020}and\u{0020}other\u{0020}necessary\u{0020}services.\nContractors\u{0020}may\u{0020}have\u{0020}their\u{0020}own\u{0020}privacy\u{0020}policies.\u{0020}Please\u{0020}refer\u{0020}to\u{0020}their\u{0020}websites\u{0020}for\u{0020}details.\n\n5.Cookies\u{0020}and\u{0020}Similar\u{0020}Technologies\nBy\u{0020}using\u{0020}our\u{0020}Service,\u{0020}you\u{0020}consent\u{0020}to\u{0020}our\u{0020}use\u{0020}of\u{0020}cookies\u{0020}and\u{0020}similar\u{0020}tracking\u{0020}technologies\u{0020}to\u{0020}collect\u{0020}information\u{0020}for\u{0020}analyzing\u{0020}trends\u{0020}and\u{0020}administering\u{0020}the\u{0020}Service.\u{0020}Cookies\u{0020}are\u{0020}small\u{0020}data\u{0020}files\u{0020}placed\u{0020}on\u{0020}your\u{0020}device\u{0020}to\u{0020}remember\u{0020}your\u{0020}preferences\u{0020}and\u{0020}activities\u{0020}on\u{0020}our\u{0020}Service.\nManaging\u{0020}Cookies:\u{0020}You\u{0020}can\u{0020}control\u{0020}cookie\u{0020}use\u{0020}through\u{0020}your\u{0020}browser\u{0020}or\u{0020}mobile\u{0020}device\u{0020}settings.\u{0020}If\u{0020}you\u{0020}disable\u{0020}cookies,\u{0020}some\u{0020}features\u{0020}of\u{0020}the\u{0020}Service\u{0020}may\u{0020}not\u{0020}function\u{0020}properly,\u{0020}such\u{0020}as\u{0020}signing\u{0020}in\u{0020}or\u{0020}accessing\u{0020}certain\u{0020}features.\nPersonal\u{0020}Data:\u{0020}If\u{0020}cookies\u{0020}are\u{0020}linked\u{0020}to\u{0020}personally\u{0020}identifiable\u{0020}information,\u{0020}we\u{0020}treat\u{0020}this\u{0020}information\u{0020}as\u{0020}personal\u{0020}data.\nFor\u{0020}more\u{0020}information\u{0020}on\u{0020}managing\u{0020}cookies,\u{0020}refer\u{0020}to\u{0020}your\u{0020}browser\u{0020}or\u{0020}mobile\u{0020}device’s\u{0020}help\u{0020}resources.\n\n6.Data\u{0020}Retention\nWe\u{0020}will\u{0020}retain\u{0020}your\u{0020}personal\u{0020}data\u{0020}only\u{0020}as\u{0020}long\u{0020}as\u{0020}necessary\u{0020}to\u{0020}fulfill\u{0020}the\u{0020}purposes\u{0020}for\u{0020}which\u{0020}it\u{0020}was\u{0020}collected,\u{0020}comply\u{0020}with\u{0020}legal\u{0020}obligations,\u{0020}resolve\u{0020}disputes,\u{0020}and\u{0020}enforce\u{0020}agreements.\nData\u{0020}Deletion:\u{0020}Upon\u{0020}expiration\u{0020}of\u{0020}the\u{0020}retention\u{0020}period,\u{0020}we\u{0020}will\u{0020}delete,\u{0020}block,\u{0020}or\u{0020}anonymize\u{0020}your\u{0020}personal\u{0020}data\u{0020}as\u{0020}required\u{0020}by\u{0020}law.\nUser\u{0020}Requests:\u{0020}If\u{0020}you\u{0020}request\u{0020}to\u{0020}remove\u{0020}or\u{0020}delete\u{0020}your\u{0020}data,\u{0020}we\u{0020}will\u{0020}evaluate\u{0020}whether\u{0020}it\u{0020}is\u{0020}necessary\u{0020}for\u{0020}our\u{0020}legitimate\u{0020}business\u{0020}interests,\u{0020}such\u{0020}as\u{0020}legal\u{0020}compliance\u{0020}or\u{0020}dispute\u{0020}resolution.\u{0020}Removing\u{0020}or\u{0020}deleting\u{0020}data\u{0020}may\u{0020}impact\u{0020}your\u{0020}ability\u{0020}to\u{0020}use\u{0020}certain\u{0020}services.\n\n7.Sensitive\u{0020}Personal\u{0020}Data\nSubject\u{0020}to\u{0020}the\u{0020}following\u{0020}paragraph,\u{0020}we\u{0020}ask\u{0020}that\u{0020}you\u{0020}not\u{0020}send\u{0020}us,\u{0020}and\u{0020}you\u{0020}not\u{0020}disclose,\u{0020}any\u{0020}sensitive\u{0020}personal\u{0020}data\u{0020}(e.g.,\u{0020}social\u{0020}security\u{0020}numbers,\u{0020}information\u{0020}related\u{0020}to\u{0020}racial\u{0020}or\u{0020}ethnic\u{0020}origin,\u{0020}political\u{0020}opinions,\u{0020}religion\u{0020}or\u{0020}other\u{0020}beliefs,\u{0020}health,\u{0020}biometrics\u{0020}or\u{0020}genetic\u{0020}characteristics,\u{0020}criminal\u{0020}background\u{0020}or\u{0020}trade\u{0020}union\u{0020}membership)\u{0020}on\u{0020}or\u{0020}through\u{0020}our\u{0020}Forums,\u{0020}Social\u{0020}Media,\u{0020}Service\u{0020}or\u{0020}otherwise\u{0020}to\u{0020}us.\nIf\u{0020}you\u{0020}send\u{0020}or\u{0020}disclose\u{0020}any\u{0020}sensitive\u{0020}personal\u{0020}data\u{0020}to\u{0020}us\u{0020}when\u{0020}you\u{0020}submit\u{0020}user\u{0020}generated\u{0020}content\u{0020}to\u{0020}our\u{0020}Forums,\u{0020}Social\u{0020}Media\u{0020}or\u{0020}Service,\u{0020}you\u{0020}consent\u{0020}to\u{0020}our\u{0020}processing\u{0020}and\u{0020}use\u{0020}of\u{0020}such\u{0020}sensitive\u{0020}personal\u{0020}data\u{0020}in\u{0020}accordance\u{0020}with\u{0020}this\u{0020}Policy.\u{0020}If\u{0020}you\u{0020}do\u{0020}not\u{0020}consent\u{0020}to\u{0020}our\u{0020}processing\u{0020}and\u{0020}use\u{0020}ofsuch\u{0020}sensitive\u{0020}personal\u{0020}data,\u{0020}you\u{0020}must\u{0020}not\u{0020}submit\u{0020}such\u{0020}user\u{0020}generated\u{0020}content\u{0020}toour\u{0020}Forums,\u{0020}Social\u{0020}Media,\u{0020}Service\u{0020}or\u{0020}otherwise\u{0020}to\u{0020}us.\n\n8.Securing\u{0020}Your\u{0020}Data\nWe\u{0020}prioritize\u{0020}the\u{0020}security\u{0020}of\u{0020}your\u{0020}data\u{0020}and\u{0020}implement\u{0020}a\u{0020}range\u{0020}of\u{0020}measures\u{0020}to\u{0020}protect\u{0020}it\u{0020}from\u{0020}unauthorized\u{0020}access,\u{0020}loss,\u{0020}destruction,\u{0020}or\u{0020}alteration.\u{0020}These\u{0020}measures\u{0020}include\u{0020}administrative,\u{0020}technical,\u{0020}and\u{0020}physical\u{0020}safeguards\u{0020}such\u{0020}as\u{0020}access\u{0020}control\u{0020}and\u{0020}encryption.\nHowever,\u{0020}please\u{0020}be\u{0020}aware\u{0020}that\u{0020}no\u{0020}method\u{0020}of\u{0020}transmission\u{0020}over\u{0020}the\u{0020}internet\u{0020}or\u{0020}electronic\u{0020}storage\u{0020}is\u{0020}completely\u{0020}secure.\u{0020}We\u{0020}recommend\u{0020}you\u{0020}take\u{0020}precautions\u{0020}to\u{0020}protect\u{0020}your\u{0020}personal\u{0020}data,\u{0020}including\u{0020}using\u{0020}strong,\u{0020}unique\u{0020}passwords,\u{0020}securing\u{0020}your\u{0020}browser,\u{0020}and\u{0020}avoiding\u{0020}sharing\u{0020}personal\u{0020}information\u{0020}unnecessarily.\nIn\u{0020}the\u{0020}event\u{0020}of\u{0020}a\u{0020}security\u{0020}breach,\u{0020}we\u{0020}will\u{0020}notify\u{0020}you\u{0020}electronically\u{0020}and\u{0020}may\u{0020}post\u{0020}a\u{0020}notice\u{0020}on\u{0020}our\u{0020}website.\u{0020}We\u{0020}will\u{0020}also\u{0020}report\u{0020}serious\u{0020}breaches\u{0020}to\u{0020}authorities\u{0020}and\u{0020}cooperate\u{0020}with\u{0020}them\u{0020}to\u{0020}prevent\u{0020}further\u{0020}harm.\n\n9.Age\u{0020}Limits\u{0020}and\u{0020}Children\u{0020}Protection\nYou\u{0020}must\u{0020}be\u{0020}of\u{0020}legal\u{0020}age\u{0020}in\u{0020}your\u{0020}jurisdiction\u{0020}to\u{0020}use\u{0020}our\u{0020}services.\u{0020}If\u{0020}you\u{0020}are\u{0020}underage,\u{0020}you\u{0020}must\u{0020}have\u{0020}consent\u{0020}from\u{0020}a\u{0020}parent\u{0020}or\u{0020}guardian\u{0020}to\u{0020}use\u{0020}our\u{0020}services.\nWe\u{0020}do\u{0020}not\u{0020}knowingly\u{0020}collect\u{0020}personal\u{0020}data\u{0020}from\u{0020}children\u{0020}without\u{0020}parental\u{0020}consent.\u{0020}We\u{0020}encourage\u{0020}parents\u{0020}and\u{0020}guardians\u{0020}to\u{0020}supervise\u{0020}their\u{0020}children's\u{0020}use\u{0020}of\u{0020}our\u{0020}services\u{0020}and\u{0020}to\u{0020}prevent\u{0020}them\u{0020}from\u{0020}disclosing\u{0020}personal\u{0020}information.\u{0020}If\u{0020}we\u{0020}discover\u{0020}that\u{0020}we\u{0020}have\u{0020}collected\u{0020}such\u{0020}data,\u{0020}we\u{0020}will\u{0020}delete\u{0020}it\u{0020}promptly.\u{0020}If\u{0020}you\u{0020}believe\u{0020}we\u{0020}have\u{0020}data\u{0020}about\u{0020}a\u{0020}child,\u{0020}please\u{0020}contact\u{0020}us.\n\n10.Contact\u{0020}and\u{0020}Complaints\nFor\u{0020}any\u{0020}questions\u{0020}about\u{0020}this\u{0020}Privacy\u{0020}Policy\u{0020}or\u{0020}to\u{0020}address\u{0020}concerns\u{0020}about\u{0020}your\u{0020}personal\u{0020}data,\u{0020}please\u{0020}contact\u{0020}us\u{0020}at\u{0020}Connect@gmgm.co.jp.\nGENNMUGAME\u{0020}CO.,\u{0020}LTD.\n\n\n\nSUPPLEMENTAL\u{0020}JURISDICTION-SPECIFIC\u{0020}TERMS\nCertain\u{0020}jurisdictions\u{0020}have\u{0020}additional\u{0020}legal\u{0020}requirements\u{0020}for\u{0020}users\u{0020}of\u{0020}our\u{0020}Game\u{0020}Services.\u{0020}If\u{0020}you\u{0020}reside\u{0020}in\u{0020}one\u{0020}of\u{0020}the\u{0020}jurisdictions\u{0020}listed\u{0020}below,\u{0020}the\u{0020}additional\u{0020}terms\u{0020}specified\u{0020}under\u{0020}your\u{0020}jurisdiction\u{0020}will\u{0020}apply\u{0020}to\u{0020}you\u{0020}alongside\u{0020}the\u{0020}general\u{0020}terms\u{0020}outlined\u{0020}in\u{0020}our\u{0020}privacy\u{0020}policy.\nCalifornia\nThis\u{0020}section\u{0020}applies\u{0020}to\u{0020}California\u{0020}residents\u{0020}under\u{0020}the\u{0020}California\u{0020}Consumer\u{0020}Privacy\u{0020}Act\u{0020}of\u{0020}2018\u{0020}(\"CCPA\").\nCollection\u{0020}and\u{0020}Disclosure\u{0020}of\u{0020}Personal\u{0020}Information\nIn\u{0020}the\u{0020}past\u{0020}12\u{0020}months,\u{0020}we\u{0020}have\u{0020}collected\u{0020}and\u{0020}disclosed\u{0020}the\u{0020}following\u{0020}categories\u{0020}of\u{0020}personal\u{0020}information:\n\nIdentifiers:\u{0020}Username,\u{0020}open\u{0020}ID/user\u{0020}ID,\u{0020}nickname,\u{0020}IP\u{0020}address,\u{0020}device\u{0020}ID,\u{0020}operating\u{0020}system,\u{0020}device\u{0020}type,\u{0020}email\u{0020}address,\u{0020}and\u{0020}social\u{0020}media\u{0020}profile.\nService\u{0020}Usage\u{0020}Data:\u{0020}Gameplay\u{0020}data,\u{0020}in-game\u{0020}interactions,\u{0020}and\u{0020}geolocation\u{0020}information.\nCommercial\u{0020}Information:\u{0020}Transaction\u{0020}details,\u{0020}such\u{0020}as\u{0020}products\u{0020}purchased\u{0020}and\u{0020}their\u{0020}cost.\nCustomer\u{0020}Support\u{0020}Information:\u{0020}Information\u{0020}related\u{0020}to\u{0020}customer\u{0020}support\u{0020}and\u{0020}security.\nOther\u{0020}Information:\u{0020}As\u{0020}described\u{0020}in\u{0020}Section\u{0020}1.\nWe\u{0020}have\u{0020}not\u{0020}sold\u{0020}personal\u{0020}information\u{0020}of\u{0020}California\u{0020}residents\u{0020}as\u{0020}defined\u{0020}by\u{0020}the\u{0020}CCPA.\n\nCalifornia\u{0020}Residents'\u{0020}Rights\nRight\u{0020}to\u{0020}Opt-Out:\u{0020}California\u{0020}residents\u{0020}can\u{0020}opt-out\u{0020}of\u{0020}the\u{0020}sale\u{0020}of\u{0020}their\u{0020}personal\u{0020}information.\u{0020}We\u{0020}do\u{0020}not\u{0020}sell\u{0020}personal\u{0020}information\u{0020}of\u{0020}residents\u{0020}under\u{0020}16\u{0020}years\u{0020}old.\nRight\u{0020}to\u{0020}Know:\u{0020}California\u{0020}residents\u{0020}may\u{0020}request,\u{0020}free\u{0020}of\u{0020}charge,\u{0020}a\u{0020}copy\u{0020}of\u{0020}the\u{0020}personal\u{0020}information\u{0020}we\u{0020}have\u{0020}collected\u{0020}about\u{0020}them\u{0020}in\u{0020}the\u{0020}past\u{0020}12\u{0020}months.\u{0020}This\u{0020}includes\u{0020}details\u{0020}on\u{0020}how\u{0020}we\u{0020}handle\u{0020}their\u{0020}personal\u{0020}information.\u{0020}To\u{0020}make\u{0020}this\u{0020}request,\u{0020}email\u{0020}us\u{0020}at\u{0020}Connect@gmgm.co.jp.\u{0020}We\u{0020}will\u{0020}respond\u{0020}within\u{0020}30\u{0020}days.\u{0020}You\u{0020}can\u{0020}make\u{0020}this\u{0020}request\u{0020}up\u{0020}to\u{0020}twice\u{0020}every\u{0020}12\u{0020}months.\nRight\u{0020}to\u{0020}Deletion:California\u{0020}residents\u{0020}can\u{0020}request\u{0020}the\u{0020}deletion\u{0020}of\u{0020}their\u{0020}personal\u{0020}information,\u{0020}except\u{0020}where\u{0020}exemptions\u{0020}apply.\u{0020}To\u{0020}make\u{0020}this\u{0020}request,\u{0020}email\u{0020}us\u{0020}at\u{0020}Connect@gmgm.co.jp.\u{0020}We\u{0020}will\u{0020}respond\u{0020}within\u{0020}30\u{0020}days.\nRight\u{0020}to\u{0020}Non-Discrimination:The\u{0020}CCPA\u{0020}prohibits\u{0020}discrimination\u{0020}against\u{0020}California\u{0020}residents\u{0020}for\u{0020}exercising\u{0020}their\u{0020}rights\u{0020}under\u{0020}the\u{0020}CCPA.\u{0020}Discrimination\u{0020}may\u{0020}exist\u{0020}where\u{0020}a\u{0020}business\u{0020}denies\u{0020}or\u{0020}provides\u{0020}a\u{0020}different\u{0020}level\u{0020}or\u{0020}quality\u{0020}of\u{0020}goods\u{0020}or\u{0020}services,\u{0020}or\u{0020}charges\u{0020}(or\u{0020}suggests\u{0020}that\u{0020}it\u{0020}will\u{0020}charge)\u{0020}different\u{0020}prices,\u{0020}rates,\u{0020}or\u{0020}penalties\u{0020}on\u{0020}residents\u{0020}who\u{0020}exercise\u{0020}their\u{0020}CCPA\u{0020}rights,\u{0020}unless\u{0020}doing\u{0020}so\u{0020}is\u{0020}reasonably\u{0020}related\u{0020}to\u{0020}the\u{0020}value\u{0020}provided\u{0020}to\u{0020}the\u{0020}business\u{0020}by\u{0020}the\u{0020}residents'\u{0020}data.\nFinancial\u{0020}Incentives:We\u{0020}do\u{0020}not\u{0020}currently\u{0020}offer\u{0020}financial\u{0020}incentives\u{0020}related\u{0020}to\u{0020}the\u{0020}collection,\u{0020}sale,\u{0020}or\u{0020}deletion\u{0020}of\u{0020}personal\u{0020}information.\nShine-the-Light\u{0020}Law:We\u{0020}do\u{0020}not\u{0020}share\u{0020}personal\u{0020}information\u{0020}with\u{0020}unaffiliated\u{0020}third\u{0020}parties\u{0020}for\u{0020}their\u{0020}own\u{0020}direct\u{0020}marketing\u{0020}purposes\u{0020}unless\u{0020}you\u{0020}agree\u{0020}to\u{0020}such\u{0020}disclosure.\u{0020}If\u{0020}you\u{0020}believe\u{0020}your\u{0020}information\u{0020}has\u{0020}been\u{0020}shared,\u{0020}contact\u{0020}us\u{0020}to\u{0020}request\u{0020}a\u{0020}list\u{0020}of\u{0020}third\u{0020}parties\u{0020}with\u{0020}whom\u{0020}we\u{0020}have\u{0020}shared\u{0020}your\u{0020}information.\u{0020}You\u{0020}may\u{0020}make\u{0020}one\u{0020}request\u{0020}per\u{0020}year.", "0", "0"},
